using namespace std;

class Task {
public:
    ofstream out;
    istream* in;

    Task() {
        ifstream* fin = new ifstream("input.txt");
        if (fin->is_open()) {
            in = fin;
            out.open("output.txt");
        } else {
            delete fin;
            in = &cin;
            out.rdbuf(cout.rdbuf());
        }
    }

    void execute() {
        int t = 1;
        while (t > 0) {
            process();
            t--;
        }
        out.flush();
        // No need to close cin or cout
    }

    const int mod = 1000000007;

    void process() {
        int n;
        *in >> n;
        vector<vector<int>> dp(2 * n, vector<int>(n + 1, 0));
        dp[0][1] = 1;
        for (int i = 1; i < 2 * n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j + 1 <= n) {
                    dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j]) % mod;
                }
                if (j - 1 >= 0) {
                    dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j]) % mod;
                }
            }
        }
        int answer = 0;
        for (int i = 2 * n - 2; i >= 0; i -= 2) {
            for (int j = 0; j <= n; j++) {
                if (j <= 2 * n - 1 - i && j % 2 == 1) {
                    answer = (answer + dp[i][j]) % mod;
                }
            }
        }
        out << answer;
    }
};

int main() {
    Task task;
    task.execute();
    return 0;
}

